import{_ as r}from"./chunks/fbfde974df5a5b37323f.Dk8Uta6m.js";import{_ as o,C as a,o as s,c as n,j as p,a as l,E as m,a5 as c}from"./chunks/framework.DNkHA0lr.js";const w=JSON.parse('{"title":"如何掌控你的专注力","description":"","frontmatter":{"title":"如何掌控你的专注力","originalTitle":"How To Master Your Focus","date":"2022-07-09","originalUrl":"https://thedankoe.com/letters/how-to-master-your-focus/","minutes":10,"sourceHash":"15274ce3e630ab0a5107951f9e806f5c4fdb364f552b39fc118ced3b80d0b7e9","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/how-to-master-your-focus/"}]]},"headers":[],"relativePath":"letters/how-to-master-your-focus.md","filePath":"letters/how-to-master-your-focus.md"}'),i={name:"letters/how-to-master-your-focus.md"};function h(u,e,f,d,b,k){const t=a("ArticleMeta");return s(),n("div",null,[e[0]||(e[0]=p("h1",{id:"如何掌控你的专注力",tabindex:"-1"},[l("如何掌控你的专注力 "),p("a",{class:"header-anchor",href:"#如何掌控你的专注力","aria-label":'Permalink to "如何掌控你的专注力"'},"​")],-1)),m(t),e[1]||(e[1]=c('<p><a href="https://www.youtube.com/embed/0nBBh9Gzx1g?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>我最喜欢的书之一是大卫·戴达（David Deida）所著的 <em>The Way Of The Superior Man</em>（《男人的阳刚之道》）。</p><p>大卫对现代男子气概有一些极具颠覆性的见解。他为围绕它的误解带来了一束独特的光芒，并为处理人际关系提供了一种灵性的方法。我最喜欢大卫的哪一点？<em>他的文笔。</em></p><p>他的文字有种与众不同的特质。有些内容明明说不通……却又合情合理。你可以看出戴达不是在用大脑写作，而是在用心写作。他不仅仅是在口头上谈论灵性，他更是在践行（或者说书写）灵性。</p><p>他将自己沉浸在当下，从内心最深处的本源汲取灵感。他连接着无限、上帝、宇宙、更高的智慧……且处于完全觉知状态。戴达在写作时，仿佛悬浮在物质地面几英尺之上的半空中。他是在描绘一幅画卷。他是在“展现，而不是说教”。他试图通过解释它像什么，而不是它是什么，来诠释他当下的、直接的体验。</p><p>这让我对写作本身有了很多感悟。当我能坐下来，不受干扰，活在当下，并用那些在无意识的目光看来也许毫无逻辑的语言来表达时，我就能写出最好的作品。</p><p>没有过多的思考。直接从本源流淌到屏幕。</p><p>是什么阻碍了人们达到这种状态？我让瓦茨（Watts）来为大家揭示。</p><blockquote><p>人类的意识在作为一种觉察、敏锐和理解形式的同时，也是一种无知的形式。</p><p>我们拥有的普通日常意识，遗漏的比吸收的要多得多。</p><p>正因如此，它遗漏了极其重要的东西。</p><p>它遗漏了那些如果被我们知晓，就能平息我们的焦虑、恐惧和惊骇的事物。你看，如果我们能扩大我们的觉知，去包含那些被我们遗漏的东西，我们就会拥有一种深刻的内在宁静，因为我们都会知道那件你本不该知道的事……那些深邃的、神秘的、处于深渊之中的事物。</p><p>—— 艾伦·瓦茨（Alan Watts）</p></blockquote><p>和戴达一样，瓦茨描述的正是他在人类意识的这些“深处”所看到的东西。</p><p>让我们来探讨一下。也许这能让我们都成为更好的作家（并为我们开启人类生命的一个新维度）。</p><p><em>警告：</em> 这将是我写过的更偏向灵性或哲学色彩的一篇文章。我鼓励你带着开放的心态和渴望理解的好奇心去通读它。</p><h2 id="专注力矩阵" tabindex="-1">专注力矩阵 <a class="header-anchor" href="#专注力矩阵" aria-label="Permalink to &quot;专注力矩阵&quot;">​</a></h2><p>我正在写我的书——<em>The Art Of Focus</em>（《专注的艺术》），为了向人们揭示那些我们尚未给予足够重视的东西的深层内涵：专注力。</p><p>正因如此，专注力被严重误解了。</p><p>人们只在表面层面上<em>看到</em>它，并决定点到为止。大多数人——尤其是那些在自我提升领域的人——把它仅仅看作是偶尔用于深度工作（deep work）的工具。</p><p>在现实中，专注力就是我们生命的全部。</p><blockquote><p>1小时不间断的专注能让你完成多少事，你会感到惊讶的。</p><p>—— 丹·柯（DAN KOE）(@thedankoe) <a href="https://twitter.com/thedankoe/status/1540653535192387584?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">2022年6月25日</a></p></blockquote><p><a href="https://thedankoe.com/4-hours-of-focused-work-will-change-your-life/" target="_blank" rel="noreferrer">学习如何进入深度的、专注的工作状态</a> 是一个绝佳的方式，能让你初步体验驾驭注意力的力量。</p><ul><li>你能在2小时内完成8小时的工作量。</li><li>你能利用你一天中有限的精力。</li><li>你能把在目标上取得巨大进展变成一种习惯。</li></ul><p>我们以前都讨论过这些（坦白说，专注工作在社交媒体上已经被说得有些烂大街了）。</p><p><em>但那并不是我在上面那条推文里想表达的意思。它与专注工作无关……却又与“专注工作”息息相关。</em></p><p>让我们探讨得更<em>深</em>一点。</p><p><img src="'+r+'" alt=""></p><p>在我看来，专注力，就是有意识的注意力（conscious attention）。</p><p>意识是人类体验的本质。</p><p>注意力是我们在无限的意识领域中处理信息的方式。</p><p>专注力则是你如何操纵你的注意力，在现实中导航，以实现最佳结果的过程。</p><p>在我的书中，我为我称之为“三大支柱”的概念提出了论点。</p><p>这是我指导自己生活的总体元概念。</p><p><strong>一：专注力（Focus）</strong></p><p>你的愿景、目标、目标层级（使命）和优先行动，都是你专注的“锚点”。必须培养、提炼并反复审视这些“锚点”，才能为你提供持续的内在能量。</p><p><strong>二：能量（Energy）</strong></p><p>既然你已经有了值得投入时间和注意力的重要事情，其他一切都必须紧跟其后。所有的输入源：食物、思想、金钱、信息等等。你遇到的每一种刺激，要么有助于你的未来（包括集体影响），要么就被忽略掉。</p><p>你可以扩大、收缩、变窄或放宽你对这些特定实体的专注力，从而“接入”它们的能量场。如果你的脑海中跳出一个消极的想法，你可以通过两极化思考，将这个消极想法转化为积极的体验。</p><p><strong>三：体验（Experience）</strong></p><p>有了精准的专注力和开放的能量通道，你便能从当下的直接意识体验中去引导自己。也就是说，你要将专注力锚定在当下。在与本源相连时，你要倾尽全力“奉献你的天赋”，或者用戴达的话说去“操翻这个世界”。毫无保留。去影响世人的思想和心灵，从而影响集体的思想和心灵。</p><p>从写作或沟通的角度来思考这个问题。戴达在他的文字中，完全在当下的时刻“奉献他的天赋”。他鼓励你在与世界交流和互动时，也能充分奉献你的天赋。</p><p><em>当然，这只是冰山一角。光是解释清楚就需要用上一整本书。对于那些好奇的人，它将在明年的某个时候发布。我不着急。</em></p><p>专注焦点的收缩和扩张，是你过上有意义、快乐且不断进步的生活的法门。这是一种艺术形式。不管在外行人看来这局面有多“消极”。一切皆为心造（All Is Mind）。</p><p>狭隘的、无意识的专注会导致压力、焦虑、被动反应和烦恼。</p><p>当你发现自己正在向可预测的未来投射时，你很容易将注意力窄化到一个即将来临的压力情境上，从而把那种未来的体验拉拽到你现在的体验中。</p><p>开阔的、无意识的专注会导致你对生活的发展方向感到迷茫和不知所措。</p><p>有太多的任务、目标和生活结果会触发各种思绪、情绪和体验，除非它们被“观察者”（watcher）捕捉到。</p><p>有意识的专注——无论是变窄还是放宽——都有一辈子的用武之地，但我想重点谈谈彻底改变了我驾驭现实方式的那一个用例：</p><p><em>深度、欣赏与爱。</em></p><p>别担心，我以前也是那个听到“只要正能量”这种说法就忍不住尴尬起鸡皮疙瘩的人。在本文接下来的部分，我希望你放下所有标签、评判和本能反应。敞开心扉，超越字面上的文字，因为接下来我要挑战一下你的思维方式。</p><p><strong>柯氏通讯中场提醒</strong>：<a href="https://modernmastery.co/letter" target="_blank" rel="noreferrer">读者可以在这里花5美元加入 Modern Mastery</a>。MM 包含了170多种生活和商业策略、现场直播培训，以及来自那些建立了可持续且充满热情的一人企业（one-person businesses）的人所提供的分步路线图。</p><h2 id="无限意识" tabindex="-1">无限意识 <a class="header-anchor" href="#无限意识" aria-label="Permalink to &quot;无限意识&quot;">​</a></h2><p>有一件事将人类与其他物种最大程度地区分开来：</p><p>专注的深度。</p><p>扩张与收缩。</p><p>扩张，指的是大面积的注意力。</p><p>收缩，指的是小面积的注意力。</p><p>就像一个圆圈，根据你直接意识到的事物变大或变小。</p><p>专注力是最重要却常被人们视而不见的技能。</p><p>它是无形的。它不是物质实体。要准确指出你注意力的确切状态几乎是不可能的。你无法对其进行量化。</p><p>正因如此，以及我们之前讨论过的多种原因，绝大多数人都处于沉睡状态。他们过着预先设定好的无意识的生活。习惯性的动作、思维模式、情绪反应和各项决定，构成了他们在此刻的直接体验。</p><p>有意识的生活是更深的一层。通过练习，你能在一个全新的维度里享受生活。你开始从另一个维度来看待这个世界。</p><p>是什么阻碍了人们接入这个新维度？</p><p><a href="https://thedankoe.com/what-mushrooms-taught-me-about-life-and-business/" target="_blank" rel="noreferrer">想象一下冰山一角。</a></p><p>它矗立在水面之上。</p><p>现在，把那座冰山想象成你在现实中将要接触到的任何事物。无数的冰山共同编织出了现实的结构。</p><p>一个想法、一种情绪、一部手机、一个杯子、一株植物、一台电脑、一个单词、一封信、一个设计、一个社交媒体主页、一个纹身、一个键盘、一个按键、一件衬衫、一条腰带、一个纽扣、一个房间、一朵云、一把椅子、一种气味，或者任何你能通过感官体验直接意识到的东西。</p><p>大多数人就是这样生活的。他们看见自己所看见的（或者感受自己所感受的），然后忘掉其余的一切。没有深度。没有理解。没有意识到生命本身的相互依存。</p><p>你如何潜得更深？</p><p>通过有意识的注意力和觉察力。</p><p>你能意识到你的手机发出的电磁场（EMF）频率吗？我不是要你去<em>看见</em>或<em>感受</em>它们。我是在要求你去意识到它们的存在。把它们具象化。知道它们就在那里。让你的好奇心带你开启一场学习狂欢。去理解它是如何影响它所触及的一切的。</p><p>你能意识到你手中的咖啡吗？咖啡的化学成分是什么？谁的双手参与了咖啡的生产过程？那盛着咖啡的玻璃杯呢？</p><p>在此过程中，你是否看到了你是如何将注意力集中在某一个特定的意识产物上的？你可以把咖啡和玻璃杯分开，把分子和液体分开，并且随着你不断地扩张和收缩你的焦点——你会或多或少地察觉到无限的存在。</p><p>你能将焦点收缩到心脏的一个瓣膜，扩张到视野范围内的所有事物，并随心所欲地将注意力操纵在两者之间的任何事物上吗？</p><p>就像开车一样。有时候你很开心，摇下车窗，声嘶力竭地唱着你最爱的歌。而有时候，你却为了生存而感到恐惧，注意力高度集中在刚才瞬间跳到你车前的那只鹿上。</p><p>你是通过掌控你的专注力，在生活中去航行、去欣赏、去茁壮成长的。</p><h2 id="一个思想练习" tabindex="-1">一个思想练习 <a class="header-anchor" href="#一个思想练习" aria-label="Permalink to &quot;一个思想练习&quot;">​</a></h2><p>我们经常谈论我提出的“未知”（The Unknown）的概念。</p><p>那是一个黑暗、可怕的地方，却蕴含着无限的机遇。</p><p>它是你感知到的现实之下的一层存在。</p><p><em>想象</em> 你的自我（ego）就是你的本相（being）手里拿着的手电筒。</p><p><em>想象</em> 射出的那束光就是你的感知。</p><p><em>想象</em> 你的生命，就是你用手电筒照亮、从而产生直接意识的所有事物的顶点和集合。</p><p><em>想象</em> 你自己是一个探索“未知”的探险家。</p><p>（所有的理解都是隐喻性的，你以前<em>体验</em>过这些。语言是我们交流体验的工具。而你的直接体验则是无限的显化。）</p><p>你身处一个向无限个方向延伸的黑暗房间里。</p><p>你的愿景就是北极星，是隧道尽头那微弱的光芒。</p><p>你的目标就是微弱的烛光，勾勒出你的使命。那就是实现你愿景的道路。</p><p>拿着手电筒带来的有限意识，在这段旅程中对你没什么帮助。</p><p>自我（ego），或者说这把手电筒，通常处于一种狭隘的专注状态。光照出什么，你就看到什么。如果你背弃（或忘记）了你的愿景，你就会迷失在黑暗中。</p><p>暂时把手电筒扔掉。不，现实中没那么容易。跟我一起想象一下吧。</p><p>你的胸腔里有一团光球，你可以让它收缩和膨胀。</p><p>停。想象你胸腔里的那团光球。你能感觉到它的温度吗？带着你有意识的注意力，你能让它沿着你的身体慢慢往下移动，进入你的胃部吗？你能让那团光球继续向下，一直移动到你双腿之间——感觉到光球的边缘在你的小腿内侧放射出光芒吗？</p><p>现在，你能慢慢扩大那个光球吗？越来越大，它现在已经吞没了你的整个身体。<em>感受</em>它正在“照亮”你的血液、静脉、大脑，以及此时此刻你能意识到的任何其他东西。</p><p>将你的专注力进一步扩大，延伸到房间里。你能延伸多远？你能把你周围50英尺半径内的一切都纳入你开阔的专注视野中吗？</p><p>当你在探索未知（The Unknown）时，你能更加身临其境、更有意识地察觉到你前方的道路吗？</p><p>当你“拉远视角”时，世界上还有什么烦恼吗？</p><p>你能看到大局吗？</p><p>当你在路上遇到颠簸，你内心的光芒熄灭时，你会捡起手电筒并把焦点局限在问题上——让它成为你的整个世界吗？</p><blockquote><p>获得幸福的两个步骤：\\</p><p>聚焦于重要的事物。<br> 对其他一切拉远视角。</p><p>— DAN KOE (@thedankoe) <a href="https://twitter.com/thedankoe/status/1521057414203727873?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">May 2, 2022</a></p></blockquote><p>这也是我每天散步时最喜欢做的冥想之一。收缩和扩大你的专注力，并将你通往更美好生活的道路具象化，这很有趣。</p><p>也许有一天我会创造一套真正的流程，甚至是一段引导冥想，来进一步巩固它。</p><p>写这封信的过程很有趣。</p><p>我希望你能喜欢——尽管它不是极其讲究实用——但我认为这是一件好事，能让更多人摆脱表面化的生存状态。</p><p>下周见，</p><p>— Dan Koe</p><p><strong>本周动态</strong></p><p>没多少事。</p><p>本周没有播客或YouTube视频，因为我要为数字经济学大师（Digital Economics Masters）课程做准备。</p><p>我将与所有报名的学员一起，现场开发并发布一款产品。</p><p>你将获得一个“幕后”视角，了解用你脑海中已有的知识打造一款畅销产品是多么简单。</p><p>如果你有兴趣为未来建立一个具有杠杆效应的品牌，围绕你的兴趣创作原创内容，并通过解决你自己的问题来赚取收入——<a href="https://upgrade.digitaleconomics.school/" target="_blank" rel="noreferrer">请点击此处报名参加下一期大师课程</a>。</p><hr><p><a href="/en/letters/how-to-master-your-focus">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',111))])}const T=o(i,[["render",h]]);export{w as __pageData,T as default};
